import{money}from'../core/format.js';export const card=p=>`<article class="product-card" data-category="${p.category}"><a class="visual" href="/produkt/?id=${p.slug}"><span class="badge">${p.badge}</span><span class="glyph">${p.glyph}</span></a><div class="info"><span class="meta">${p.category} · ★ ${p.rating}</span><h3><a href="/produkt/?id=${p.slug}">${p.name}</a></h3><div class="buy"><span class="price">${money(p.price)}</span><button data-add="${p.slug}" aria-label="${p.name} hinzufügen">+</button></div></div></article>`;
